  "vite.config.ts": "import tailwindcss from '@tailwindcss/vite';\nimport react from '@vitejs/plugin-react';\nimport path from 'path';\nimport {defineConfig} from 'vite';\n\nexport default defineConfig(() => {\n  return {\n    base: './',\n    plugins: [react(), tailwindcss()],\n    resolve: {\n      alias: {\n        '@': path.resolve(__dirname, '.'),\n      },\n    },\n    server: {\n      // HMR is disabled in AI Studio via DISABLE_HMR env var.\n      // Do not modify—file watching is disabled to prevent flickering during agent edits.\n      hmr: process.env.DISABLE_HMR !== 'true',\n      // Disable file watching when DISABLE_HMR is true to save CPU during agent edits.\n      watch: process.env.DISABLE_HMR === 'true' ? null : {},\n    },\n  };\n});\n",
  "index.html": "<!doctype html>\n<html lang=\"pt-BR\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Simulador e Planilha de Parcelamento</title>\n    <meta name=\"description\" content=\"Simulador financeiro e gerador de planilhas de parcelamento com cálculo de taxas de cartão para clientes e exportação em Excel, PDF e WhatsApp.\" />\n    <meta property=\"og:title\" content=\"Simulador e Planilha de Parcelamento\" />\n    <meta property=\"og:description\" content=\"Simulador financeiro e gerador de planilhas de parcelamento com cálculo de taxas de cartão para clientes e exportação em Excel, PDF e WhatsApp.\" />\n    <meta property=\"og:type\" content=\"website\" />\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    <link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" />\n  </head>\n  <body class=\"bg-sky-50 text-slate-800 antialiased font-sans\">\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.tsx\"></script>\n  </body>\n</html>\n\n",
